card_css:
/* Variante 1: Minimalista Flat */
.sl-card {
  background-color: var(--sl-card-bg);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: .5rem;
  box-shadow: none;
  transition: all 0.2s ease-in-out;
}
.sl-card:hover {
  border-color: var(--sl-primary);
  box-shadow: 0 0 10px rgba(0, 255, 255, 0.2);
}

/* Variante 2: Glassmorphism-inspired */
.sl-card {
  background: rgba(255, 255, 255, 0.05);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: .75rem;
  box-shadow: 0 4px 30px rgba(0, 0, 0, 0.1);
  transition: all 0.3s ease-in-out;
}
.sl-card:hover {
  background: rgba(255, 255, 255, 0.1);
  border-color: var(--sl-primary);
  box-shadow: 0 0 15px rgba(0, 255, 255, 0.3);
}

/* Variante 3: Neon Outline/Glow */
.sl-card {
  background-color: var(--sl-card-bg);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: .5rem;
  box-shadow: 0 0 5px rgba(0, 0, 0, 0.5);
  transition: all 0.3s ease-in-out;
}
.sl-card:hover {
  border-color: var(--sl-primary);
  box-shadow: 0 0 20px var(--sl-primary);
}

/* Variante 4: Modern Dark/Elevated */
.sl-card {
  background-color: var(--sl-card-bg);
  border: none;
  border-radius: .75rem;
  box-shadow: 0 10px 20px rgba(0, 0, 0, 0.4), 0 0 0 1px rgba(255, 255, 255, 0.05);
  transition: transform 0.3s ease-in-out, box-shadow 0.3s ease-in-out;
}
.sl-card:hover {
  transform: translateY(-5px);
  box-shadow: 0 15px 30px rgba(0, 0, 0, 0.6), 0 0 0 2px var(--sl-primary);
}

/* Variante 5: Glowing Hover Fill */
.sl-card {
  background-color: var(--sl-card-bg);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: .5rem;
  box-shadow: none;
  transition: all 0.3s ease-in-out;
}
.sl-card:hover {
  background-color: rgba(0, 255, 255, 0.05);
  box-shadow: 0 0 15px var(--sl-primary);
  border-color: var(--sl-primary);
}

/* Variante Nova 1: Neumorphic Softness */
.sl-card {
  background-color: var(--sl-card-bg);
  border: none;
  border-radius: 12px;
  padding: 1.5rem;
  box-shadow: 
    -7px -7px 15px rgba(255, 255, 255, 0.05), /* Light source top-left */
    7px 7px 15px rgba(0, 0, 0, 0.3); /* Dark source bottom-right */
  transition: all 0.3s ease;
}
.sl-card:hover {
  box-shadow: 
    inset 3px 3px 7px rgba(0, 0, 0, 0.2), /* Inset dark */
    inset -3px -3px 7px rgba(255, 255, 255, 0.07), /* Inset light */
    0 0 0 2px var(--sl-primary); /* Subtle outline */
  transform: translateY(-2px);
}

/* Variante Nova 2: Brutalist Grid */
.sl-card {
  background-color: var(--sl-card-bg);
  border: 1px solid var(--sl-text-main); /* Stark border */
  border-radius: 0; /* No rounded corners */
  padding: 1.5rem;
  box-shadow: none;
  transition: all 0.2s ease-out;
  position: relative;
}
.sl-card:hover {
  border-color: var(--sl-primary); /* Primary accent on hover */
  box-shadow: 5px 5px 0 0 var(--sl-primary); /* Offset shadow for brutalist effect */
  transform: translate(-5px, -5px); /* Move card up-left to reveal shadow */
}

/* Variante Nova 3: Editorial Accent Line */
.sl-card {
  background-color: var(--sl-card-bg);
  border: none;
  border-radius: 0.25rem; /* Slightly rounded, but emphasis on line */
  padding: 1.5rem 1.5rem 1.5rem 2rem; /* More padding on left for accent line */
  box-shadow: 0 4px 8px rgba(0, 0, 0, 0.2); /* Clean, subtle shadow */
  position: relative;
  transition: all 0.3s ease;
}
.sl-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 5px; /* Accent line width */
  height: 100%;
  background-color: var(--sl-text-main); /* Default line color */
  transition: background-color 0.3s ease, width 0.3s ease;
}
.sl-card:hover::before {
  background-color: var(--sl-primary); /* Primary color on hover */
  width: 8px; /* Slightly wider line on hover */
}
.sl-card:hover {
  box-shadow: 0 6px 12px rgba(0, 0, 0, 0.3);
}

/* Variante Nova 4: Cyber Terminal Frame */
.sl-card {
  background-color: var(--sl-card-bg);
  border: 2px dashed rgba(255, 255, 255, 0.4); /* Dashed border for terminal look, using white with transparency */
  border-radius: 0; /* Sharp edges */
  padding: 1.5rem;
  box-shadow: none;
  font-family: 'monospace', 'Courier New', monospace; /* Monospaced font */
  color: var(--sl-text-main); /* Ensure text is visible */
  transition: border-color 0.3s ease, box-shadow 0.3s ease;
}
.sl-card .card-title {
  color: var(--sl-primary); /* Title highlight */
  text-shadow: 0 0 5px var(--sl-primary); /* Subtle text glow */
}
.sl-card:hover {
  border-color: var(--sl-primary); /* Primary border on hover */
  box-shadow: 0 0 10px rgba(var(--sl-primary), 0.5); /* Subtle glow around card */
}

/* Variante Nova 5: Fluid Organic Edge */
.sl-card {
  background-color: var(--sl-card-bg);
  border: none;
  padding: 1.5rem;
  box-shadow: 0 8px 16px rgba(0, 0, 0, 0.2); /* Soft, natural shadow */
  border-radius: 30% 70% 70% 30% / 30% 30% 70% 70%; /* Initial blob shape */
  transition: all 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94); /* Smooth, organic transition */
}
.sl-card:hover {
  border-radius: 70% 30% 30% 70% / 70% 70% 30% 30%; /* Another blob shape on hover */
  box-shadow: 0 12px 24px rgba(0, 0, 0, 0.3), 0 0 0 2px var(--sl-primary); /* Enhanced shadow + subtle primary ring */
  transform: translateY(-3px);
}
